// #6a993d78df85add81c766e3c — AC4: бизнес открывает отчёт своего кандидата без причины доступа,
// user (מנהל מגייס) — только назначенных ему. Кейс ACL-009. Только чтение — @prod-safe.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';

type Cand = { id: string; report_status?: string | null };

async function candidates(page: Page): Promise<Cand[]> {
  const api = await openWithApi(page, '/candidates');
  const res = await api.rpc('list_candidates');
  expect(res.status(), 'list_candidates').toBe(200);
  return (await res.json()) as Cand[];
}

/** Открывает отчёт и возвращает p_reason из запроса get_candidate_report. */
async function openReport(page: Page, id: string) {
  const req = page.waitForRequest((r) => r.url().includes('/rpc/get_candidate_report'));
  await page.goto(`/candidates/${id}/report`);
  return (await req).postDataJSON() as { p_candidate_id: string; p_reason: string | null };
}

async function expectReportWithoutReason(page: Page) {
  await expect(page.getByTestId('attempt-view')).toBeVisible();
  await expect(page.getByText('דוח תצפית על השיחה הרשמית')).toBeVisible();
  await expect(page.getByText('נדרשת סיבת גישה')).toHaveCount(0);
  await expect(page.getByRole('dialog')).toHaveCount(0);
}

test.describe('Отчёт кандидата в контуре бизнеса — без причины доступа (#6a993d78df85add81c766e3c)', () => {
  test('business — свой кандидат без причины; user — назначенный открывается, неназначенный «המועמד לא נמצא» @desktop @prod-safe #6a993d78df85add81c766e3c', async ({ asUser }) => {
    const business = await asUser('business');
    const user = await asUser('user');

    const bizCands = await candidates(business);
    const userCands = await candidates(user);
    const userIds = new Set(userCands.map((c) => c.id));
    const foreign = bizCands.find((c) => c.report_status === 'ready' && !userIds.has(c.id));
    expect(foreign, 'нет кандидата testim с готовым отчётом, не назначенного user').toBeTruthy();
    const own = userCands.find((c) => c.report_status === 'ready') ?? userCands[0];
    expect(own, 'у user нет назначенных кандидатов').toBeTruthy();

    // business: AC4 «הגישה מותרת ללא סיבת גישה».
    const bizReq = await openReport(business, foreign!.id);
    expect(bizReq.p_reason ?? null).toBeNull();
    await expectReportWithoutReason(business);

    // user: назначенный — открывается без причины.
    const userReq = await openReport(user, own!.id);
    expect(userReq.p_reason ?? null).toBeNull();
    await expectReportWithoutReason(user);

    // user: неназначенный — AC4 «נותרת מוגבלת לגבולות ההרשאה שלו».
    await user.goto(`/candidates/${foreign!.id}/report`);
    await expect(user.getByRole('heading', { name: 'המועמד לא נמצא' })).toBeVisible();
    await expect(user.getByText('ייתכן שהמועמד אינו בטיפולכם או שהקישור שגוי.')).toBeVisible();
    await expect(user.getByRole('link', { name: 'חזרה למועמדים' })).toBeVisible();
    await expect(user.getByTestId('attempt-view')).toHaveCount(0);
  });
});
